function textNodes(state: State, selected?: Set<string>): CanvasDisplayNode[] {
  const nodes: CanvasDisplayNode[] = [];
  const visit = (box: State['document']['scene']['root']) => {
    if (box.kind === 'container') { box.children.forEach(visit); return; }
    const id = `grid:${box.id}`;
    if (selected && !selected.has(id)) return;
    const original = state.document.scene.contents[box.contentId], content = original.content, view = state.canvas.diagramViews?.[id];
    const refs = getDiagramRevision(original.revisionId).nodeRefs;
    const highlights = presentationHighlights(original, state.document.diagramPresentations?.[box.contentId], refs);
    const diagram = highlights === original.highlights ? original : { ...original, highlights };
    nodes.push({ id, boxId: box.id, version: state.version, layout: 'grid', kind: 'diagram', childIds: [], expansion: box.collapsed ? 'collapsed' : 'expanded',
      // Geometry is deliberately absent from the public small projection below.
      nodeRefs: refs, geometry: { units: 'cells', bounds: { column: 0, row: 0, columns: 0, rows: 0 } }, content, diagram,
      collapsible: { self: true, subtrees: diagramContentNodes(content).filter(n => n.childIds.length).map(n => ({ contentNodeId: n.id,
        label: n.label, line: n.line, branchColumn: n.branchColumn,
        expansion: view?.contentRevisionId === content.revisionId && view.collapsedContentNodeIds.includes(n.id) ? 'collapsed' : 'expanded' })) } });
  };
  visit(state.document.scene.root);
  return nodes;
}
/** Select on the producer side; source evidence is complete for the selected diagrams. */
export function currentCanvasRead(state: State, options: { level: 'small' | 'full'; nodeIds?: string[] }) {
  const selected = options.nodeIds && new Set(options.nodeIds);
  const raw = options.level === 'small' ? textNodes(state, selected) : canvasDisplayNodes(state.document, state.canvas, state.version, state.cell, state.endpointBounds);
  const nodes = raw.filter(node => !selected || selected.has(node.id)).map(node => {
    if (node.layout !== 'grid') return node;
    const { textRows: _rows, presentation: _presentation, presentationSettings: _settings, domainNode: _domain, content, contentNodes: _nodes, nodeRefs, diagram, geometry, ...rest } = node;
    const { asciiSha256: _hash, ...text } = content ?? {};
    const { content: _content, sourceContext: _source, ...metadata } = diagram ?? {};
    const { contentHash: _sourceHash, ...sourceContext } = diagram?.sourceContext ?? {};
    const activeHighlights = new Set(diagram && activeDiagramHighlights(diagram.content, diagram.highlights, diagram.revisionId).map(h => h.id));
    const activeJumps = new Set(diagram && activeDiagramJumps(diagram.content, diagram.jumps).map(j => j.id));
    return { ...rest, ...(options.level === 'full' ? { geometry } : {}),
      ...(content ? { content: { ...text, structure: { ...content.structure, nodes: Object.fromEntries(diagramContentNodes(content).map(n => [n.id, {
        ...n, ...(nodeRefs?.[n.id] ? { nodeRef: nodeRefs[n.id] } : {}), sourceRanges: diagram?.sourceContext.mappings.filter(m => m.line === n.line && m.startColumn <= n.endColumn && m.endColumn >= n.startColumn)
          .flatMap(m => { const range = diagram.sourceContext.evidence[m.entityId]?.sourceRanges[m.sourceRangeIndex];
            return range ? [{ path: range.path, startLine: range.startLine, endLine: range.endLine }] : []; }) ?? []
      }])) } } } : {}),
      ...(diagram ? { diagram: { ...metadata, sourceContext,
        highlights: diagram.highlights?.map(h => ({ ...h, status: activeHighlights.has(h.id) ? 'active' : 'stale' })),
        jumps: diagram.jumps?.map(j => { const { contentHash: _hash, ...source } = j.source;
          return { ...j, source, status: activeJumps.has(j.id) ? 'active' : 'stale' }; }) } } : {}) };
  });
  return { level: options.level, version: state.version, nodes,
    ...(options.level === 'full' ? { edges: state.document.edges, view: state.canvas } : {}) };
}

import { agentTrajectorySchema } from '../../core/agents/agentContext';
import { z } from 'zod';

const id = z.string().min(1).max(200);
const version = z.number().int().nonnegative();
const rect = z.object({ startLine: z.number().int().positive(), endLine: z.number().int().positive(),
  startColumn: z.number().int().positive(), endColumn: z.number().int().positive() }).strict();
export const liveRegionSchema = z.object({
  id, sourceBoxId: id, sourceContentId: id, rect,
  text: z.string().max(2_000_000), stale: z.boolean()
}).strict();
export type LiveRegion = z.infer<typeof liveRegionSchema>;
const diagramIds = z.array(id.refine(value => value.startsWith('grid:'), 'Expected a nodes.list() grid ID')).max(1000).optional();
const metadata = { documentId: id, canvasEpoch: id, sequence: version, documentVersion: version };
export const liveSelectionSchema = z.object({ ...metadata, regions: z.array(liveRegionSchema).max(1000), diagramIds }).strict();
export const liveSelectionDeltaSchema = z.object({ ...metadata, baseSequence: version, diagramIds,
  upserted: z.array(liveRegionSchema).max(1000), removed: z.array(id).max(1000) }).strict();
export type LiveSelection = z.infer<typeof liveSelectionSchema>;
export type LiveSelectionDelta = z.infer<typeof liveSelectionDeltaSchema>;
const pastePosition = z.object({ column: version, row: version }).strict();
export const livePasteSchema = z.object({ type: z.literal('diagram.paste'), requestId: id,
  expectedVersion: version, text: z.string().min(1).max(41000), position: pastePosition }).strict();
export type LivePaste = z.infer<typeof livePasteSchema>;
export const livePasteCommandSchema = z.object({ type: z.literal('diagram.paste.command'), commandId: id,
  documentId: id, canvasEpoch: id, expectedVersion: version, ascii: z.string().min(1).max(20000),
  nodeId: id, position: pastePosition }).strict();
export type LivePasteCommand = z.infer<typeof livePasteCommandSchema>;
export const livePasteReplySchema = z.object({ type: z.literal('diagram.paste.reply'), commandId: id,
  result: z.discriminatedUnion('ok', [
    z.object({ ok: z.literal(true), version, nodeId: id }).strict(),
    z.object({ ok: z.literal(false), code: id, error: z.string().max(4000) }).strict()
  ]) }).strict();
export type LivePasteReply = z.infer<typeof livePasteReplySchema>;
/** Copy stages ephemeral text; the user chooses the position/version when pasting. */
export const liveCopySchema = z.object({ type: z.literal('diagram.copy'), requestId: id,
  text: z.string().min(1).max(41000) }).strict();
export type LiveCopy = z.infer<typeof liveCopySchema>;
export const liveCopyCommandSchema = z.object({ type: z.literal('diagram.copy.command'), commandId: id,
  documentId: id, canvasEpoch: id, ascii: z.string().min(1).max(20000) }).strict();
export type LiveCopyCommand = z.infer<typeof liveCopyCommandSchema>;
export const liveCopyReplySchema = z.object({ type: z.literal('diagram.copy.reply'), commandId: id,
  result: z.discriminatedUnion('ok', [z.object({ ok: z.literal(true) }).strict(),
    z.object({ ok: z.literal(false), code: id, error: z.string().max(4000) }).strict()]) }).strict();
export type LiveCopyReply = z.infer<typeof liveCopyReplySchema>;
export const liveCanvasMessageSchema = z.discriminatedUnion('type', [
  z.object({ type: z.literal('attach'), protocolVersion: z.literal(2), workspaceInstanceId: id, documentId: id, includeContext: z.boolean().optional() }).strict(),
  z.object({ type: z.literal('context.get'), requestId: id }).strict(),
  livePasteSchema,
  livePasteReplySchema,
  liveCopySchema,
  liveCopyReplySchema,
  agentTrajectorySchema.extend({ type: z.literal('agent-context.upload'), requestId: id }),
  z.object({ type: z.literal('publish'), protocolVersion: z.literal(2), workspaceInstanceId: id,
    capabilities: z.array(id).max(32).optional() }).strict(),
  liveSelectionSchema.extend({ type: z.literal('selection.snapshot') }),
  liveSelectionDeltaSchema.extend({ type: z.literal('selection.delta') }),
  z.object({ type: z.literal('remove'), documentId: id, canvasEpoch: id }).strict()
]);
export interface BoundSelection extends LiveSelection {
  protocolVersion: 2; connectionId: string; workspaceInstanceId: string; receivedAt: string;
}
export interface LiveCanvasContext {
  version: number; name?: string;
  nodes: import('../workspace/canvasDisplayNode').CanvasDisplayNode[];
  edges: import('../../core/diagrams/diagramConnection').DiagramConnection[];
}
export type ApiLiveCanvasContext = Omit<LiveCanvasContext, 'nodes'> & {
  apiFormatVersion: typeof import('./apiRepresentation').canvasApiFormatVersion;
  nodes: import('./apiRepresentation').ApiDisplayNode[];
};
export type LiveCanvasEvent = ({ type: 'attached'; context?: ApiLiveCanvasContext } & BoundSelection)
  | LivePasteCommand
  | LiveCopyCommand
  | { type: 'diagram.copied'; requestId: string; connectionId: string; workspaceInstanceId: string;
      documentId: string; canvasEpoch: string }
  | { type: 'diagram.pasted'; requestId: string; connectionId: string; workspaceInstanceId: string;
      documentId: string; canvasEpoch: string; nodeId: string; version: number }
  | { type: 'context.snapshot'; requestId: string; connectionId: string; workspaceInstanceId: string; documentId: string; canvasEpoch: string; context: ApiLiveCanvasContext }
  | ({ type: 'selection.delta' } & LiveSelectionDelta & Pick<BoundSelection, 'connectionId' | 'workspaceInstanceId' | 'receivedAt'>)
  | { type: 'canvas.disconnected' | 'canvas.closed' | 'canvas.replaced'; connectionId: string; canvasEpoch: string }
  | { type: 'error'; code: string; error: string; requestId?: string }
  | { type: 'agent-context.uploaded'; requestId: string; connectionId: string; agentContextId: string;
      contentHash: string; agentType: string; sourceSessionId: string; messageCount: number }
  | { type: 'publisher.ready'; protocolVersion: 2 }
  | { type: 'agents.changed'; count: number };

export function sameRegion(a: LiveRegion, b: LiveRegion): boolean {
  return a === b || a.id === b.id && a.sourceBoxId === b.sourceBoxId && a.sourceContentId === b.sourceContentId
    && a.stale === b.stale && a.text === b.text && a.rect.startLine === b.rect.startLine && a.rect.endLine === b.rect.endLine
    && a.rect.startColumn === b.rect.startColumn && a.rect.endColumn === b.rect.endColumn;
}
export function sameDiagramSelection(a: readonly string[] = [], b: readonly string[] = []): boolean {
  const ids = new Set(a);
  return ids.size === b.length && b.every(id => ids.has(id));
}
/** Compare against the last transmitted snapshot, never against a dropped pending delta. */
export function selectionDelta(previous: LiveSelection, next: LiveSelection): LiveSelectionDelta {
  const before = new Map(previous.regions.map(region => [region.id, region]));
  const after = new Set(next.regions.map(region => region.id));
  return { documentId: next.documentId, canvasEpoch: next.canvasEpoch, sequence: next.sequence,
    documentVersion: next.documentVersion, baseSequence: previous.sequence,
    ...(!sameDiagramSelection(previous.diagramIds, next.diagramIds) ? { diagramIds: next.diagramIds ?? [] } : {}),
    upserted: next.regions.filter(region => !before.has(region.id) || !sameRegion(before.get(region.id)!, region)),
    removed: previous.regions.filter(region => !after.has(region.id)).map(region => region.id) };
}

import { randomUUID } from 'node:crypto';
import type { CanvasSessionPort } from '../../../application/mapping/agent/ports';
import type { CanvasCommand, CanvasDescriptor } from '../../../domain/mapping/agent/contracts';
export class CanvasSessionBridge implements CanvasSessionPort {
  private canvases = new Map<string, { descriptor: CanvasDescriptor; touched: number; commands: CanvasCommand[]; wake?: () => void }>();
  private pending = new Map<string, { canvasId: string; resolve: (value: unknown) => void; reject: (error: Error) => void; timer: ReturnType<typeof setTimeout> }>();
  register(descriptor: CanvasDescriptor) {
    const old = this.canvases.get(descriptor.canvasId);
    if (old) { old.descriptor = structuredClone(descriptor); old.touched = Date.now(); }
    else this.canvases.set(descriptor.canvasId, { descriptor: structuredClone(descriptor), touched: Date.now(), commands: [] });
  }
  list() {
    for (const [id, entry] of this.canvases) if (Date.now() - entry.touched > 35000) this.unregister(id);
    return [...this.canvases.values()].map(entry => structuredClone(entry.descriptor));
  }
  async poll(canvasId: string) {
    const entry = this.canvases.get(canvasId);
    if (!entry) throw new Error('CANVAS_UNAVAILABLE');
    entry.touched = Date.now();
    if (!entry.commands.length) await new Promise<void>(resolve => {
      entry.wake?.();
      const timer = setTimeout(done, 15000);
      function done() { clearTimeout(timer); if (entry!.wake === done) entry!.wake = undefined; resolve(); }
      entry.wake = done;
    });
    entry.touched = Date.now();
    return entry.commands.splice(0);
  }
  dispatch(canvasId: string, command: Omit<CanvasCommand, 'id'>): Promise<unknown> {
    this.list();
    const entry = this.canvases.get(canvasId);
    if (!entry) return Promise.reject(new Error('CANVAS_UNAVAILABLE: open Mapping and attach again'));
    if (this.pending.size >= 100) return Promise.reject(new Error('Too many pending canvas commands'));
    return new Promise((resolve, reject) => {
      const id = randomUUID();
      const timer = setTimeout(() => {
        this.pending.delete(id); entry.commands = entry.commands.filter(command => command.id !== id);
        reject(new Error('CANVAS_TIMEOUT: outcome may be unknown; retry with the same requestId'));
      }, 25000);
      this.pending.set(id, { canvasId, resolve, reject, timer });
      entry.commands.push({ ...command, id }); entry.wake?.();
    });
  }
  reply(canvasId: string, commandId: string, result: { value?: unknown; error?: string }) {
    const pending = this.pending.get(commandId);
    if (!pending || pending.canvasId !== canvasId) return;
    clearTimeout(pending.timer); this.pending.delete(commandId);
    if (result.error) pending.reject(new Error(result.error)); else pending.resolve(result.value);
  }
  unregister(canvasId: string) {
    this.canvases.get(canvasId)?.wake?.(); this.canvases.delete(canvasId);
    for (const [id, pending] of this.pending) if (pending.canvasId === canvasId) {
      clearTimeout(pending.timer); pending.reject(new Error('CANVAS_UNAVAILABLE')); this.pending.delete(id);
    }
  }
  dispose() { [...this.canvases.keys()].forEach(id => this.unregister(id)); }
}

import { newAsyncContext } from 'quickjs-emscripten';
import type { AgentExecRuntime } from '../../../application/mapping/agent/ports';
import { canvasMethods } from '../../../domain/mapping/agent/contracts';
export class QuickJsAgentRuntime implements AgentExecRuntime {
  async run(code: string, invoke: (method: string, args: unknown) => Promise<unknown>) {
    const context = await newAsyncContext();
    const deadline = Date.now() + 30000;
    let interrupts = 0, calls = 0;
    context.runtime.setMemoryLimit(32 * 1024 * 1024);
    context.runtime.setMaxStackSize(512 * 1024);
    context.runtime.setInterruptHandler(() => Date.now() > deadline || ++interrupts > 20000);
    try {
      const call = context.newAsyncifiedFunction('__call', async (method, json) => {
        if (++calls > 100) throw new Error('Execution exceeds 100 API calls');
        const value = await invoke(context.getString(method), JSON.parse(context.getString(json)));
        const result = JSON.stringify(value ?? null);
        if (Buffer.byteLength(result) > 4 * 1024 * 1024) throw new Error('API result exceeds 4MB');
        return context.newString(result);
      });
      context.setProp(context.global, '__call', call); call.dispose();
      const groups = ['canvas','nodes','edges'].map(group => `const ${group} = Object.freeze({${Object.keys(canvasMethods).filter(name => name.startsWith(`${group}.`)).map(name => `${name.split('.')[1]}: (args = {}) => JSON.parse(__call(${JSON.stringify(name)}, JSON.stringify(args)))`).join(',')}});`).join('\n');
      const result = await context.evalCodeAsync(`"use strict"; ${groups}\nJSON.stringify((function() {\n${code}\n})() ?? null)`);
      if (result.error) { const error = context.dump(result.error); result.error.dispose(); throw new Error(error?.message ?? String(error)); }
      const json = context.getString(result.value); result.value.dispose();
      if (Buffer.byteLength(json) > 4 * 1024 * 1024) throw new Error('Execution result exceeds 4MB');
      return JSON.parse(json);
    } finally { context.dispose(); }
  }
}

import { canvasReply, mutationCommands } from '../../../../domain/mapping/agent/canvasReply';
import { publishLiveCanvasSelections, type LiveAgentStatus } from './liveCanvasPublisher';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import { useEffect, useRef, useState } from 'react';
import type { CanvasCommand, CanvasDescriptor } from '../../../../domain/mapping/agent/contracts';
import { apiFetch, errorFrom } from '../../../shared/http/http';
import { browserStableWorkspaceId } from './stableWorkspaceIdentity';

export function useAgentCanvasBridge(descriptor: Omit<CanvasDescriptor, 'canvasId' | 'stableWorkspaceId'>, handle: (command: CanvasCommand) => Promise<unknown>, workspace?: CanvasWorkspace, canMutate: () => boolean = () => true) {
  const [agentStatus, setAgentStatus] = useState<LiveAgentStatus>({ connected: false, count: 0 });
  const [canvasId] = useState(() => crypto.randomUUID());
  const [identity, setIdentity] = useState<{ stableWorkspaceId?: string }>();
  useEffect(() => {
    let active = true;
    void browserStableWorkspaceId(import.meta.env.BASE_URL).then(stableWorkspaceId => {
      if (active) setIdentity({ stableWorkspaceId });
    });
    return () => { active = false; };
  }, []);
  const latest = useRef({ descriptor, handle, canMutate }); latest.current = { descriptor, handle, canMutate };
  const registration = identity && JSON.stringify({ ...descriptor, canvasId, ...identity });
  useEffect(() => {
    if (!registration) return;
    void apiFetch('/api/mapping/agent/canvases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: registration }).catch(() => undefined);
  }, [registration]);
  useEffect(() => {
    if (!identity) return;
    const abort = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const results = new Map<string, { value?: unknown; error?: string }>();
    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
      if (!response.ok) throw await errorFrom(response);
      return response.json();
    };
    const register = () => request('/canvases', { ...latest.current.descriptor, canvasId, ...identity });
    const run = async () => {
      try {
        await register();
        while (!abort.signal.aborted) {
          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
          for (const command of commands) {
            const started = performance.now();
            let result = results.get(command.id);
            if (!result) {
              try { result = { value: await latest.current.handle(command) }; }
              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
              if (mutationCommands.has(command.method)) results.set(command.id, result);
              if (results.size > 200) results.delete(results.keys().next().value!);
            }
            const handled = performance.now();
            const reply = canvasReply(command, result);
            const encoded = performance.now();
            const response = await apiFetch(`/api/mapping/agent/canvases/${canvasId}/reply`, { method: 'POST', signal: abort.signal,
              headers: { 'content-type': 'application/json', 'x-canvas-command-id': command.id }, body: reply.body });
            if (!response.ok) {
              // A proxy/backend can enforce a lower limit. Resolve the pending command immediately.
              await request(`/canvases/${canvasId}/reply`, { commandId: command.id,
                error: `CANVAS_REPLY_REJECTED: method=${command.method} actualBytes=${reply.bytes} status=${response.status}; retry the identical requestId if this was a mutation` });
            }
            console.debug('canvas-reply', { method: command.method, bytes: reply.bytes, handleMs: Math.round(handled - started), encodeMs: Math.round(encoded - handled), replyMs: Math.round(performance.now() - encoded), durationMs: Math.round(performance.now() - started), oversized: reply.oversized });
          }
          await register();
        }
      } catch {
        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
      }
    };
    void run();
    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
    // React cleanup does not run on page reload. Retire this ephemeral instance
    // promptly, without ever deleting a replacement that has the same stable ID.
    window.addEventListener('pagehide', unregister);
    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
  }, [canvasId, identity]);
  useEffect(() => {
    setAgentStatus({ connected: false, count: 0 });
    if (!workspace || !identity) return;
    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
    endpoint.protocol = endpoint.protocol === 'https:' ? 'wss:' : 'ws:';
    return publishLiveCanvasSelections(workspace, canvasId, endpoint.href, setAgentStatus, () => latest.current.canMutate());
  }, [workspace, canvasId, identity]);
  return { canvasId, agentStatus };
}

import { selectedDiagramIds } from '../../../../domain/mapping/selection/selectionState';
import { selectionClipboardText } from '../../../../domain/mapping/workspace/selectionClipboard';
import { asciiForSelection } from '../../../../domain/core/diagrams/diagramSelection';
import { formatAsciiWithCodeReferences } from '../../../../domain/core/diagrams/diagramClipboard';
import type { Diagram, GridBox } from '../../../../domain/core/diagrams/lineGrid';
import { sameDiagramSelection, sameRegion, selectionDelta, type LiveRegion, type LiveSelection } from '../../../../domain/mapping/agent/liveCanvasStatus';
import type { MappingPocGridRect } from '../../../../domain/mapping/selection/mappingPoc';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import type { CanvasSession } from '../workspace/canvasSession';
import { LiveCanvasPasteReceiver } from './liveCanvasPaste';
import { LiveCanvasCopyReceiver } from './liveCanvasCopy';

/** Read completed regions only; pointer previews, pane geometry and history are not published. */
export function observeCanvasSelection(session: CanvasSession, documentId: string, changed: (snapshot: LiveSelection) => void) {
  const canvasEpoch = crypto.randomUUID();
  let sequence = 0, stopped = false, timer: ReturnType<typeof setTimeout> | undefined;
  let previous: LiveSelection | undefined;
  const cache = new Map<string, { diagram?: Diagram; rectKey: string; ids: readonly string[]; contentNodeIds?: readonly string[]; sourceAscii?: string; region: LiveRegion }>();
  const rectKey = (boxId: string, rect: MappingPocGridRect) => JSON.stringify([boxId, rect.startLine, rect.endLine, rect.startColumn, rect.endColumn]);
  const sample = () => {
    timer = undefined;
    if (stopped) return;
    const snapshot = session.controller.getSnapshot(), { selection } = snapshot.canvas;
    const boxes = new Map<string, string>();
    const visit = (box: GridBox) => {
      if (box.kind === 'container') box.children.forEach(visit);
      else boxes.set(box.id, box.contentId);
    };
    visit(snapshot.document.scene.root);
    const diagramIds = selectedDiagramIds(selection);
    const regions: LiveRegion[] = [];
    const add = (id: string, sourceBoxId: string, sourceContentId: string, rect: MappingPocGridRect,
      ids: readonly string[], sourceAscii?: string, contentNodeIds?: readonly string[]) => {
      const diagram = snapshot.document.scene.contents[sourceContentId];
      const stale = sourceAscii !== undefined && (!diagram || diagram.content.ascii !== sourceAscii || boxes.get(sourceBoxId) !== sourceContentId);
      const key = rectKey(sourceBoxId, rect), cached = cache.get(id);
      if (cached && cached.diagram === diagram && cached.rectKey === key && cached.ids === ids && cached.contentNodeIds === contentNodeIds
        && cached.sourceAscii === sourceAscii && cached.region.stale === stale && cached.region.sourceContentId === sourceContentId) {
        regions.push(cached.region); return;
      }
      const text = stale ? cached?.sourceAscii === sourceAscii ? cached.region.text : formatAsciiWithCodeReferences([asciiForSelection(sourceAscii!, rect)], [])
        : diagram ? selectionClipboardText(diagram, rect, ids, contentNodeIds)! : '';
      const region = { id, sourceBoxId, sourceContentId, rect, text, stale };
      cache.set(id, { diagram, rectKey: key, ids, contentNodeIds, sourceAscii, region }); regions.push(region);
    };
    for (const item of selection.items) if (item.region) {
      const { sourceContentId, sourceAscii, rect, selectedIds, contentNodeIds } = item.region;
      add(item.id, item.displayNodeId.slice(5), sourceContentId, rect, selectedIds, sourceAscii, contentNodeIds);
    }
    const liveIds = new Set(regions.map(region => region.id));
    for (const id of cache.keys()) if (!liveIds.has(id)) cache.delete(id);
    const before = new Map(previous?.regions.map(region => [region.id, region]));
    if (previous && sameDiagramSelection(previous.diagramIds, diagramIds) && before.size === regions.length && regions.every(region => before.has(region.id) && sameRegion(before.get(region.id)!, region))) return;
    previous = { documentId, canvasEpoch, sequence: sequence++, documentVersion: snapshot.version, regions, diagramIds };
    changed(previous);
  };
  const unsubscribe = session.controller.subscribe(() => { timer ??= setTimeout(sample, 0); });
  sample();
  return { canvasEpoch, dispose() { stopped = true; clearTimeout(timer); unsubscribe(); } };
}

export interface LiveAgentStatus { connected: boolean; count: number }

/** One publisher socket per browser workspace; reconnects with current, bounded snapshots. */
export function publishLiveCanvasSelections(workspace: CanvasWorkspace, workspaceInstanceId: string, endpoint: string, onAgentStatus?: (status: LiveAgentStatus) => void, canMutate: () => boolean = () => true) {
  let socket: WebSocket | undefined, ready = false, disposed = false;
  let reconnect: ReturnType<typeof setTimeout> | undefined, drainTimer: ReturnType<typeof setTimeout> | undefined;
  const entries = new Map<string, { session: CanvasSession; observer: ReturnType<typeof observeCanvasSelection> }>();
  const latest = new Map<string, LiveSelection>();
  const sent = new Map<string, LiveSelection>();
  const pending = new Map<string, LiveSelection | { documentId: string; canvasEpoch: string }>();
  const paste = new LiveCanvasPasteReceiver();
  const copy = new LiveCanvasCopyReceiver();
  const drain = () => {
    clearTimeout(drainTimer);
    drainTimer = undefined;
    if (!ready || socket?.readyState !== WebSocket.OPEN) return;
    for (const [id, value] of pending) {
      if (socket.bufferedAmount > 64 * 1024) { drainTimer = setTimeout(drain, 20); return; }
      if ('regions' in value) {
        const previous = sent.get(id);
        socket.send(JSON.stringify(previous?.canvasEpoch === value.canvasEpoch
          ? { type: 'selection.delta', ...selectionDelta(previous, value) }
          : { type: 'selection.snapshot', ...value }));
        sent.set(id, value);
      } else { socket.send(JSON.stringify({ type: 'remove', ...value })); sent.delete(id); }
      pending.delete(id);
    }
  };
  const refresh = () => {
    const drafts = workspace.store.getState().drafts;
    for (const [id, entry] of entries) if (!drafts[id] || drafts[id].hidden || drafts[id].session !== entry.session) {
      entry.session.cursorCopy.clear();
      entry.observer.dispose(); entries.delete(id); latest.delete(id);
      pending.set(id, { documentId: id, canvasEpoch: entry.observer.canvasEpoch });
    }
    for (const [id, draft] of Object.entries(drafts)) if (!draft.hidden && !entries.has(id)) {
      const observer = observeCanvasSelection(draft.session, id, value => {
        latest.set(id, value); pending.set(id, value); drain();
      });
      entries.set(id, { session: draft.session, observer });
    }
    drain();
  };
  const unsubscribe = workspace.store.subscribe(refresh);
  refresh();
  const connect = () => {
    if (disposed) return;
    const ws = socket = new WebSocket(endpoint);
    ready = false;
    ws.onopen = () => ws.send(JSON.stringify({ type: 'publish', protocolVersion: 2, workspaceInstanceId, capabilities: ['diagram.copy'] }));
    ws.onmessage = event => {
      const message = JSON.parse(event.data);
      if (message.type === 'publisher.ready') {
        onAgentStatus?.({ connected: true, count: 0 });
        ready = true; sent.clear(); pending.clear(); latest.forEach((value, id) => pending.set(id, value)); drain();
      } else if (message.type === 'agents.changed') {
        onAgentStatus?.({ connected: true, count: message.count });
      } else if (message.type === 'diagram.copy.command' && ready) {
        const draft = workspace.store.getState().drafts[message.documentId];
        const entry = entries.get(message.documentId);
        const epoch = entry?.session === draft?.session ? entry?.observer.canvasEpoch : undefined;
        ws.send(JSON.stringify(copy.apply(message, draft, epoch, canMutate())));
      } else if (message.type === 'diagram.paste.command' && ready) {
        const draft = workspace.store.getState().drafts[message.documentId];
        const entry = entries.get(message.documentId);
        const epoch = entry?.session === draft?.session ? entry?.observer.canvasEpoch : undefined;
        ws.send(JSON.stringify(paste.apply(message, draft, epoch, canMutate())));
      } else if (message.type === 'error') ws.close(); // Registration may be racing this connection; retry with fresh state.
    };
    ws.onerror = () => ws.close();
    ws.onclose = () => {
      entries.forEach(entry => entry.session.cursorCopy.clear());
      ready = false; clearTimeout(drainTimer);
      if (!disposed) onAgentStatus?.({ connected: false, count: 0 });
      if (!disposed) reconnect = setTimeout(connect, 1000);
    };
  };
  connect();
  return () => {
    entries.forEach(entry => entry.session.cursorCopy.clear());
    disposed = true; ready = false; clearTimeout(reconnect); clearTimeout(drainTimer);
    unsubscribe(); entries.forEach(entry => entry.observer.dispose()); entries.clear(); pending.clear(); latest.clear();
    socket?.close();
  };
}
